// FILE: apps/desktop/src/main/services/splitTrainingDatasets.service.js
//
// UPDATED (2026-03-17)
//
// Purpose:
//   Create explicit train/val splits for both datasets generated by exportTrainingDatasets:
//     - datasets/finish_raw/<finish>/...        -> datasets/finish_explicit/{train,val}/<finish>/...
//     - datasets/identity_raw/<set-number>/...  -> datasets/identity_explicit/{train,val}/<set-number>/...
//
// Key features:
// - Prefer hardlinks (no duplication). Fallback to copy.
// - Deterministic splitting (seeded shuffle).
// - Leakage-safe mode via grouping:
//    - identity dataset: group by identity class folder (ssp-082) by definition.
//    - finish dataset: group by identity parsed from filename prefix (set-number) so the same card
//      doesn't appear in both train and val across finishes.
//
// CHANGES (2026-03-17):
// - FIX: minPerIdentityTrain floor lowered from 2 -> 1 (single-image classes are now included).
// - FIX: Single-image classes always assigned to train; val bootstrapped by Python pipeline
//        (bootstrap_validation_set) rather than being skipped entirely.

import fs from "node:fs";
import path from "node:path";

const DEFAULT_IMAGE_EXTS = new Set([".jpg", ".jpeg", ".png", ".webp"]);

function ensureDir(absDir) {
  if (!fs.existsSync(absDir)) fs.mkdirSync(absDir, { recursive: true });
}

function rmDir(absDir) {
  try {
    fs.rmSync(absDir, { recursive: true, force: true });
  } catch {
    // ignore
  }
}

function listDirs(absDir) {
  if (!fs.existsSync(absDir)) return [];
  return fs
    .readdirSync(absDir, { withFileTypes: true })
    .filter((d) => d.isDirectory())
    .map((d) => d.name);
}

function listFiles(absDir) {
  if (!fs.existsSync(absDir)) return [];
  return fs
    .readdirSync(absDir, { withFileTypes: true })
    .filter((d) => d.isFile())
    .map((d) => d.name);
}

function isImageFile(name) {
  const ext = path.extname(name).toLowerCase();
  return DEFAULT_IMAGE_EXTS.has(ext);
}

/**
 * Deterministic PRNG (Mulberry32).
 */
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function hashSeed(str) {
  const s = String(str || "");
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function shuffleDeterministic(arr, seed) {
  const rnd = mulberry32(seed);
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rnd() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

/**
 * Hardlink if possible, otherwise copy.
 */
function linkOrCopy(srcAbs, dstAbs, prefer = "hardlink") {
  if (fs.existsSync(dstAbs)) return { modeUsed: "skip_exists" };

  ensureDir(path.dirname(dstAbs));

  if (prefer === "hardlink") {
    try {
      fs.linkSync(srcAbs, dstAbs);
      return { modeUsed: "hardlink" };
    } catch {
      // fallthrough to copy
    }
  }

  fs.copyFileSync(srcAbs, dstAbs);
  return { modeUsed: "copy" };
}

/**
 * Extract identity key from canonical filename: "<setCode>-<number>__..."
 * Returns "ssp-082" or "" if cannot parse.
 */
function parseIdentityFromFilename(filename) {
  const base = path.basename(filename);
  const m = base.match(/^([a-z0-9]+-\d{3,4})__/i);
  if (!m) return "";
  return String(m[1] || "").toLowerCase();
}

/**
 * Create split assignments for grouped keys.
 * Returns: { trainKeys: Set, valKeys: Set }
 */
function splitKeys(keys, { valRatio, seed }) {
  const n = keys.length;
  const valCount = Math.max(1, Math.round(n * valRatio));
  const shuffled = shuffleDeterministic(keys, seed);

  const val = new Set(shuffled.slice(0, valCount));
  const train = new Set(shuffled.slice(valCount));

  // Ensure non-empty train if possible
  if (train.size === 0 && shuffled.length > 1) {
    const one = shuffled[0];
    val.delete(one);
    train.add(one);
  }

  return { trainKeys: train, valKeys: val };
}

/**
 * Split identity_raw into identity_explicit/{train,val} by class folders (already grouped).
 *
 * Classes with exactly 1 image are always assigned to train only.
 * The Python bootstrap_validation_set() will duplicate the image into val before training.
 */
function splitIdentityRaw(identityRawAbs, identityExplicitAbs, opts, report) {
  const classesAll = listDirs(identityRawAbs);

  // Each entry: { cls, count }
  const eligibleClasses = [];

  for (const cls of classesAll) {
    const srcDir = path.join(identityRawAbs, cls);
    const files = listFiles(srcDir).filter(isImageFile);

    // Health tracking
    report.health.identityPerClass[cls] = files.length;

    if (files.length < opts.minPerIdentityWarn) {
      report.health.warnings.push({
        type: "low_identity_count",
        identity: cls,
        count: files.length,
        recommendedMin: opts.minPerIdentityWarn,
      });
    }

    // Skip only if truly empty
    if (files.length < opts.minPerIdentityTrain) {
      report.health.warnings.push({
        type: "skipped_identity_class_too_small",
        identity: cls,
        count: files.length,
        minRequired: opts.minPerIdentityTrain,
      });
      continue;
    }

    eligibleClasses.push({ cls, count: files.length });
  }

  // splitKeys operates on class name strings only
  const seed = hashSeed(`${opts.seed}|identity`);
  const { trainKeys, valKeys } = splitKeys(
    eligibleClasses.map((e) => e.cls),
    { valRatio: opts.valRatio, seed }
  );

  for (const { cls, count } of eligibleClasses) {
    const srcDir = path.join(identityRawAbs, cls);
    const files = listFiles(srcDir).filter(isImageFile);

    // Single-image classes always go to train.
    // bootstrap_validation_set() in the Python pipeline will duplicate into val.
    const split = count === 1 || !valKeys.has(cls) ? "train" : "val";

    const dstDir = path.join(identityExplicitAbs, split, cls);
    ensureDir(dstDir);

    for (const f of files) {
      const srcAbs = path.join(srcDir, f);
      const dstAbs = path.join(dstDir, f);
      const r = linkOrCopy(srcAbs, dstAbs, opts.prefer);
      report.used[r.modeUsed] = (report.used[r.modeUsed] || 0) + 1;
      report.counts.identityFiles++;
      report.counts.identity[split]++;
    }
  }
}

/**
 * Split finish_raw into finish_explicit/{train,val} using leakage-safe grouping by identity key.
 */
function splitFinishRaw(finishRawAbs, finishExplicitAbs, opts, report) {
  const finishClasses = listDirs(finishRawAbs);

  // Build identity -> list of { finish, file }
  const byIdentity = new Map();

  for (const finish of finishClasses) {
    const srcDir = path.join(finishRawAbs, finish);
    const files = listFiles(srcDir).filter(isImageFile);

    // Per-finish health
    report.health.finishPerClass[finish] = files.length;
    if (files.length < opts.minPerFinishWarn) {
      report.health.warnings.push({
        type: "low_finish_count",
        finish,
        count: files.length,
        recommendedMin: opts.minPerFinishWarn,
      });
    }

    for (const f of files) {
      const identity = parseIdentityFromFilename(f);
      const key = identity || `unknown:${finish}:${f}`;

      if (!byIdentity.has(key)) byIdentity.set(key, []);
      byIdentity.get(key).push({ finish, file: f });
    }
  }

  const identityKeys = Array.from(byIdentity.keys()).sort();
  const seed = hashSeed(`${opts.seed}|finish`);
  const { trainKeys, valKeys } = splitKeys(identityKeys, {
    valRatio: opts.valRatio,
    seed,
  });

  for (const identity of identityKeys) {
    const split = valKeys.has(identity) ? "val" : "train";
    const items = byIdentity.get(identity) || [];

    for (const { finish, file } of items) {
      const srcAbs = path.join(finishRawAbs, finish, file);
      const dstAbs = path.join(finishExplicitAbs, split, finish, file);
      ensureDir(path.dirname(dstAbs));

      const r = linkOrCopy(srcAbs, dstAbs, opts.prefer);
      report.used[r.modeUsed] = (report.used[r.modeUsed] || 0) + 1;
      report.counts.finishFiles++;
      report.counts.finish[split]++;
    }
  }
}

/**
 * Public entrypoint
 */
export function splitTrainingDatasets(workspacePath, opts = {}) {
  const datasetsRoot = path.join(workspacePath, "datasets");

  const identityRawAbs = path.join(datasetsRoot, "identity_raw");
  const finishRawAbs = path.join(datasetsRoot, "finish_raw");

  const identityExplicitAbs = path.join(datasetsRoot, "identity_explicit");
  const finishExplicitAbs = path.join(datasetsRoot, "finish_explicit");

  const clean = opts.clean !== false;
  const prefer = opts.prefer === "copy" ? "copy" : "hardlink";
  const valRatio =
    typeof opts.valRatio === "number" && opts.valRatio > 0 && opts.valRatio < 0.9
      ? opts.valRatio
      : 0.2;

  const seed = String(opts.seed ?? "visionlab-v1");

  const minPerFinishWarn = Number.isFinite(opts.minPerFinishWarn)
    ? Number(opts.minPerFinishWarn)
    : 50;

  const minPerIdentityWarn = Number.isFinite(opts.minPerIdentityWarn)
    ? Number(opts.minPerIdentityWarn)
    : 5;

  // Lowered floor to 1: single-image classes are included in train.
  // Val is handled downstream by bootstrap_validation_set() in the Python pipeline.
  const minPerIdentityTrain = Number.isFinite(opts.minPerIdentityTrain)
    ? Math.max(1, Number(opts.minPerIdentityTrain))
    : 1;

  const report = {
    ok: true,
    workspacePath,
    prefer,
    valRatio,
    seed,

    used: { hardlink: 0, copy: 0, skip_exists: 0 },

    counts: {
      finishFiles: 0,
      identityFiles: 0,
      finish: { train: 0, val: 0 },
      identity: { train: 0, val: 0 },
    },

    health: {
      warnings: [],
      finishPerClass: {},
      identityPerClass: {},
    },
  };

  if (!fs.existsSync(identityRawAbs)) {
    return {
      ok: false,
      error:
        "identity_raw not found. Run exportTrainingDatasets first to create datasets/identity_raw.",
    };
  }

  if (!fs.existsSync(finishRawAbs)) {
    return {
      ok: false,
      error:
        "finish_raw not found. Run exportTrainingDatasets first to create datasets/finish_raw.",
    };
  }

  if (clean) {
    rmDir(identityExplicitAbs);
    rmDir(finishExplicitAbs);
  }

  ensureDir(path.join(identityExplicitAbs, "train"));
  ensureDir(path.join(identityExplicitAbs, "val"));
  ensureDir(path.join(finishExplicitAbs, "train"));
  ensureDir(path.join(finishExplicitAbs, "val"));

  splitIdentityRaw(
    identityRawAbs,
    identityExplicitAbs,
    { prefer, valRatio, seed, minPerIdentityWarn, minPerFinishWarn, minPerIdentityTrain },
    report
  );

  splitFinishRaw(
    finishRawAbs,
    finishExplicitAbs,
    { prefer, valRatio, seed, minPerIdentityWarn, minPerFinishWarn, minPerIdentityTrain },
    report
  );

  return report;
}